create extension if not exists "pgcrypto";
create type public.app_role as enum ('user','artist_pending','artist_verified','organizer','admin');
create type public.event_status as enum ('draft','published','cancelled');
create type public.ticket_status as enum ('valid','used','refunded','cancelled');
create type public.order_status as enum ('pending','paid','failed','refunded');
create type public.post_kind as enum ('event','music','update');
create table public.profiles (id uuid primary key references auth.users on delete cascade, display_name text not null default '', role public.app_role not null default 'user', avatar_path text, created_at timestamptz not null default now());
create table public.artist_profiles (profile_id uuid primary key references public.profiles on delete cascade, handle text unique not null, bio text, followers_count integer not null default 0);
create table public.organizer_profiles (profile_id uuid primary key references public.profiles on delete cascade, name text not null, stripe_account_id text unique, onboarding_complete boolean not null default false);
create table public.venues (id uuid primary key default gen_random_uuid(), organizer_id uuid references public.profiles, name text not null, city text not null, address text, latitude numeric, longitude numeric);
create table public.events (id uuid primary key default gen_random_uuid(), organizer_id uuid not null references public.profiles, venue_id uuid references public.venues, slug text unique not null, title text not null, description text, starts_at timestamptz not null, ends_at timestamptz, city text not null, genre text, cover_path text, status public.event_status not null default 'draft', created_at timestamptz not null default now());
create table public.event_artists (event_id uuid references public.events on delete cascade, artist_id uuid references public.profiles on delete cascade, primary key(event_id,artist_id));
create table public.ticket_types (id uuid primary key default gen_random_uuid(), event_id uuid not null references public.events on delete cascade, name text not null, price_cents integer not null check(price_cents>=0), currency char(3) not null default 'EUR', quantity integer not null check(quantity>0), sold_quantity integer not null default 0 check(sold_quantity>=0 and sold_quantity<=quantity), sale_starts_at timestamptz, sale_ends_at timestamptz);
create table public.orders (id uuid primary key default gen_random_uuid(), buyer_id uuid not null references public.profiles, stripe_checkout_session_id text unique, status public.order_status not null default 'pending', total_cents integer not null check(total_cents>=0), currency char(3) not null default 'EUR', created_at timestamptz not null default now());
create table public.tickets (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders, ticket_type_id uuid not null references public.ticket_types, event_id uuid not null references public.events, qr_token uuid unique not null default gen_random_uuid(), attendee_name text, status public.ticket_status not null default 'valid', created_at timestamptz not null default now());
create table public.check_ins (id uuid primary key default gen_random_uuid(), ticket_id uuid unique not null references public.tickets, event_id uuid not null references public.events, scanned_by uuid not null references public.profiles, scanned_at timestamptz not null default now());
create table public.artist_follows (follower_id uuid references public.profiles on delete cascade, artist_id uuid references public.profiles on delete cascade, created_at timestamptz not null default now(), primary key(follower_id,artist_id), check(follower_id<>artist_id));
create table public.feed_posts (id uuid primary key default gen_random_uuid(), artist_id uuid not null references public.profiles, kind public.post_kind not null, body text not null check(char_length(body)<=2000), event_id uuid references public.events, published_at timestamptz not null default now(), deleted_at timestamptz);
create table public.post_media (id uuid primary key default gen_random_uuid(), post_id uuid not null references public.feed_posts on delete cascade, path text not null, position integer not null default 0);
create table public.reports (id uuid primary key default gen_random_uuid(), reporter_id uuid not null references public.profiles, post_id uuid references public.feed_posts, reason text not null, status text not null default 'open', created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), profile_id uuid not null references public.profiles, type text not null, payload jsonb not null default '{}', read_at timestamptz, created_at timestamptz not null default now());
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
create function public.is_event_owner(p_event uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.events where id=p_event and organizer_id=auth.uid()) $$;
alter table public.profiles enable row level security; alter table public.artist_profiles enable row level security; alter table public.organizer_profiles enable row level security; alter table public.venues enable row level security; alter table public.events enable row level security; alter table public.event_artists enable row level security; alter table public.ticket_types enable row level security; alter table public.orders enable row level security; alter table public.tickets enable row level security; alter table public.check_ins enable row level security; alter table public.artist_follows enable row level security; alter table public.feed_posts enable row level security; alter table public.post_media enable row level security; alter table public.reports enable row level security; alter table public.notifications enable row level security;
create policy "public profiles" on public.profiles for select using(true); create policy "own profile" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy "public artists" on public.artist_profiles for select using(true); create policy "public venues" on public.venues for select using(true); create policy "public events" on public.events for select using(status='published' or organizer_id=auth.uid() or public.is_admin()); create policy "owner events" on public.events for all using(organizer_id=auth.uid() or public.is_admin()) with check(organizer_id=auth.uid() or public.is_admin()); create policy "public types" on public.ticket_types for select using(exists(select 1 from public.events e where e.id=event_id and (e.status='published' or e.organizer_id=auth.uid()))); create policy "owner types" on public.ticket_types for all using(public.is_event_owner(event_id)) with check(public.is_event_owner(event_id));
create policy "own orders" on public.orders for select using(buyer_id=auth.uid()); create policy "own tickets" on public.tickets for select using(exists(select 1 from public.orders o where o.id=order_id and o.buyer_id=auth.uid())); create policy "event checkins" on public.check_ins for select using(public.is_event_owner(event_id));
create policy "public posts" on public.feed_posts for select using(deleted_at is null); create policy "verified artists post" on public.feed_posts for insert with check(artist_id=auth.uid() and exists(select 1 from public.profiles where id=auth.uid() and role='artist_verified')); create policy "own posts" on public.feed_posts for update using(artist_id=auth.uid() or public.is_admin()); create policy "follows visible" on public.artist_follows for select using(true); create policy "own follows" on public.artist_follows for all using(follower_id=auth.uid()) with check(follower_id=auth.uid()); create policy "report posts" on public.reports for insert with check(reporter_id=auth.uid()); create policy "own notifications" on public.notifications for select using(profile_id=auth.uid());
insert into storage.buckets(id,name,public) values ('event-media','event-media',true),('avatars','avatars',true) on conflict do nothing;
create policy "public media" on storage.objects for select using(bucket_id in ('event-media','avatars')); create policy "authenticated upload" on storage.objects for insert to authenticated with check(bucket_id in ('event-media','avatars') and owner=auth.uid());
create function public.validate_ticket_token(p_token uuid, p_scanner uuid) returns table(result text, ticket_id uuid, attendee_name text) language plpgsql security definer set search_path=public as $$ declare v_ticket public.tickets%rowtype; begin select t.* into v_ticket from public.tickets t where t.qr_token=p_token for update; if not found then return query select 'invalid'::text,null::uuid,null::text; return; end if; if not public.is_event_owner(v_ticket.event_id) then raise exception 'not authorized'; end if; if v_ticket.status='used' then return query select 'already_used'::text,v_ticket.id,v_ticket.attendee_name; return; end if; if v_ticket.status<>'valid' then return query select 'invalid'::text,v_ticket.id,v_ticket.attendee_name; return; end if; update public.tickets set status='used' where id=v_ticket.id; insert into public.check_ins(ticket_id,event_id,scanned_by) values(v_ticket.id,v_ticket.event_id,p_scanner); return query select 'accepted'::text,v_ticket.id,v_ticket.attendee_name; end $$;
